{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C43"],
      "claim": "Codeine, the closest structural analogue, is readily and extensively absorbed orally with a reported human oral bioavailability of 40–70%, supporting F ≥ 20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Ethylmorphine, a close codeine analogue, has a minimum oral availability of 0.74 (range 0.54–0.92) in healthy subjects, supporting high oral bioavailability.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C13"],
      "claim": "Diacetylmorphine, another morphinan analogue, shows oral bioavailability of 45.6% in humans, supporting the pattern of high oral bioavailability for this scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Pethidine, a simpler opioid analogue, has an absolute oral bioavailability of 0.57 in healthy volunteers, supporting high oral bioavailability for opioid-like tertiary amines.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C46"],
      "claim": "Morphine has a lower absolute oral bioavailability of 0.196 in humans, but it lacks the methoxy group present in the query and is less structurally transferable than codeine.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C45"],
      "claim": "Cepharanthine has a low absolute oral bioavailability of 6–9% in humans, but its much larger, more complex bisbenzylisoquinoline structure is only distantly related to the query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a codeine-like morphinan with a methoxy group, hydroxyl, and tertiary amine. The closest experimental analogues, codeine and ethylmorphine, show oral bioavailability well above 20% (40–70% and 54–92%, respectively), and other related opioids also generally exceed 20%. Lower-bioavailability examples such as morphine and cepharanthine are less structurally transferable. Therefore, the prediction is high oral bioavailability (F ≥ 20%).",
  "evidence_gaps": [
    "No direct experimental bioavailability data exist for the exact query molecule.",
    "The precise stereochemical and regiochemical identity of the query relative to codeine is not fully resolved from the SMILES alone.",
    "Human first-pass metabolism and transporter effects for this specific analogue are unknown."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

